from AlgorithmImports import *
import math


class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy_symbol = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl_symbol = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm_symbol = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac_symbol = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig_symbol = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = [
            self.spy_symbol, self.aapl_symbol, self.ibm_symbol,
            self.bac_symbol, self.aig_symbol
        ]

        # SMA period not specified by the spec; using 20-day as a reasonable default
        self.spy_sma = SimpleMovingAverage(20)
        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.spy_shares = 0
        self.spy_invest_pct = 0.40

        self.aapl_rsi = RelativeStrengthIndex(14)
        self.prev_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_shares = 0
        self.aapl_buy_amount = 20000.0
        self.aapl_rsi_sell_level = 60.0
        self.aapl_red_days_required = 3

    def OnData(self, data: Slice):
        for symbol in self.required_symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        spy_bar = data.Bars[self.spy_symbol]
        aapl_bar = data.Bars[self.aapl_symbol]

        spy_close = spy_bar.Close
        aapl_close = aapl_bar.Close

        self.spy_sma.Update(spy_bar.EndTime, spy_close)
        self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self._process_strategy_a(spy_close)
        self._process_strategy_b(aapl_close)

        self.prev_aapl_close = aapl_close

    def _process_strategy_a(self, spy_close):
        if not self.spy_sma.IsReady:
            return

        spy_sma_val = self.spy_sma.Current.Value

        if self.prev_spy_close is not None and self.prev_spy_sma is not None:
            if self.spy_shares > 0:
                crosses_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < spy_sma_val)
                if crosses_below:
                    self.MarketOrder(self.spy_symbol, -self.spy_shares)
                    self.spy_shares = 0

            if self.spy_shares == 0:
                crosses_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > spy_sma_val)
                if crosses_above:
                    target_value = self.spy_invest_pct * self.Portfolio.TotalPortfolioValue
                    quantity = int(math.floor(target_value / spy_close))
                    if quantity > 0:
                        self.MarketOrder(self.spy_symbol, quantity)
                        self.spy_shares += quantity

        self.prev_spy_close = spy_close
        self.prev_spy_sma = spy_sma_val

    def _process_strategy_b(self, aapl_close):
        if self.aapl_shares > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > self.aapl_rsi_sell_level:
                self.MarketOrder(self.aapl_symbol, -self.aapl_shares)
                self.aapl_shares = 0

        if self.aapl_shares == 0:
            if self.aapl_red_streak >= self.aapl_red_days_required:
                cash = self.Portfolio.Cash
                if cash >= self.aapl_buy_amount:
                    quantity = int(math.floor(self.aapl_buy_amount / aapl_close))
                    if quantity > 0:
                        self.MarketOrder(self.aapl_symbol, quantity)
                        self.aapl_shares += quantity

from AlgorithmImports import *

class DualIndependentStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # SMA lookback isn't specified by the prompt; 50 days used as the standard trend-cross default.
        self.sma = SimpleMovingAverage(50)
        self.rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.prev_spy_close = None
        self.prev_sma_value = None
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        self.lot_a_shares = 0
        self.lot_b_shares = 0

    def OnData(self, data):
        if not all(data.Bars.ContainsKey(s) for s in self.symbols):
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # Updated manually (not auto-subscribed) so indicators only ever see days
        # where every subscribed ticker has a bar, per the "skip all rule evaluation" rule.
        self.sma.Update(self.Time, spy_close)
        self.rsi.Update(self.Time, aapl_close)

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if self.sma.IsReady and self.prev_spy_close is not None and self.prev_sma_value is not None:
            sma_value = self.sma.Current.Value
            if self.lot_a_shares > 0:
                if self._crosses_below(spy_close, sma_value, self.prev_spy_close, self.prev_sma_value):
                    self.MarketOrder(self.spy, -self.lot_a_shares)
            elif self.lot_a_shares == 0:
                if self._crosses_above(spy_close, sma_value, self.prev_spy_close, self.prev_sma_value):
                    target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                    shares = int(target_value // spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)

        if self.lot_b_shares > 0:
            if self.rsi.IsReady and self.rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.lot_b_shares)
        elif self.lot_b_shares == 0:
            if self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares = int(20000 // aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)

        self.prev_spy_close = spy_close
        if self.sma.IsReady:
            self.prev_sma_value = self.sma.Current.Value
        self.prev_aapl_close = aapl_close

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status != OrderStatus.Filled and orderEvent.Status != OrderStatus.PartiallyFilled:
            return
        filled = int(orderEvent.FillQuantity)
        if orderEvent.Symbol == self.spy:
            self.lot_a_shares += filled
        elif orderEvent.Symbol == self.aapl:
            self.lot_b_shares += filled

    def _crosses_above(self, x_today, y_today, x_prev, y_prev):
        return x_prev <= y_prev and x_today > y_today

    def _crosses_below(self, x_today, y_today, x_prev, y_prev):
        return x_prev >= y_prev and x_today < y_today

