from AlgorithmImports import *
import math


class StrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {t: self.AddEquity(t, Resolution.Daily).Symbol for t in tickers}
        self.all_symbols = list(self.symbols.values())

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, Resolution.Daily)

        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.aapl_prev_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        for symbol in self.all_symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        spy_cross_above = False
        spy_cross_below = False
        if self.sma.IsReady and self.spy_prev_close is not None and self.spy_prev_sma is not None:
            sma_value = self.sma.Current.Value
            if self.spy_prev_close <= self.spy_prev_sma and spy_close > sma_value:
                spy_cross_above = True
            if self.spy_prev_close >= self.spy_prev_sma and spy_close < sma_value:
                spy_cross_below = True

        aapl_rsi_above_60 = self.rsi.IsReady and self.rsi.Current.Value > 60

        if self.strategy_a_shares > 0 and spy_cross_below:
            self.MarketOrder(self.spy, -self.strategy_a_shares, tag="A_SELL")

        if self.strategy_b_shares > 0 and aapl_rsi_above_60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares, tag="B_SELL")

        if self.strategy_a_shares == 0 and spy_cross_above:
            target_value = 0.4 * self.Portfolio.TotalPortfolioValue
            shares = math.floor(target_value / spy_close)
            if shares > 0:
                self.MarketOrder(self.spy, shares, tag="A_BUY")

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                shares = math.floor(20000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares, tag="B_BUY")

        self.spy_prev_close = spy_close
        if self.sma.IsReady:
            self.spy_prev_sma = self.sma.Current.Value
        self.aapl_prev_close = aapl_close

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status != OrderStatus.Filled and orderEvent.Status != OrderStatus.PartiallyFilled:
            return
        order = self.Transactions.GetOrderById(orderEvent.OrderId)
        if order is None:
            return
        fill_qty = int(orderEvent.FillQuantity)
        if order.Tag in ("A_BUY", "A_SELL"):
            self.strategy_a_shares += fill_qty
        elif order.Tag in ("B_BUY", "B_SELL"):
            self.strategy_b_shares += fill_qty

