            crossed_below_sma = self.prev_spy_close >= self.prev_spy_sma and spy_close < self.sma.Current.Value

        spy_shares = self.Portfolio[self.spy].Quantity
        if spy_shares != 0 and crossed_below_sma:
            self.Liquidate(self.spy)
            spy_shares = 0
        if spy_shares == 0 and crossed_above_sma:
            target_value = 0.4 * self.Portfolio.TotalPortfolioValue
            qty = math.floor(target_value / spy_close)
