        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        aapl_shares = self.Portfolio[self.aapl].Quantity
        if aapl_shares != 0 and self.rsi.IsReady and self.rsi.Current.Value > 60:
            self.Liquidate(self.aapl)
            aapl_shares = 0
        if aapl_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
