        self.aapl = self.symbols["AAPL"]

        # Strategy A state: SPY close vs its 100-day SMA
        self.sma100 = self.SMA(self.spy, 100, Resolution.Daily)
        self.prev_spy_close = None
        self.prev_sma100 = None

        # Strategy B state: AAPL red streak, 14-day RSI
        self.rsi14 = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        if self.IsWarmingUp:
            return

        for symbol in self.symbols.values():
            if not data.Bars.ContainsKey(symbol):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        sma_ready = self.sma100.IsReady
        today_sma = self.sma100.Current.Value if sma_ready else None
        have_prev_sma = sma_ready and self.prev_sma100 is not None

        # ---- SELLS FIRST ----

        # Strategy A sell: SPY close crosses below its 100-day SMA
        if self.Portfolio[self.spy].Invested and have_prev_sma:
            crossed_below = (self.prev_spy_close >= self.prev_sma100) and (spy_close < today_sma)
            if crossed_below:
                self.Liquidate(self.spy)

        # Strategy B sell: AAPL 14-day RSI closes above 60
        if self.Portfolio[self.aapl].Invested and self.rsi14.IsReady:
            if self.rsi14.Current.Value > 60:
                self.Liquidate(self.aapl)

        # ---- BUYS ----

        # Strategy A buy: SPY close crosses above its 100-day SMA
        if not self.Portfolio[self.spy].Invested and have_prev_sma:
            crossed_above = (self.prev_spy_close <= self.prev_sma100) and (spy_close > today_sma)
            if crossed_above:
                target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                shares = int(target_value // spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)

        # Strategy B buy: AAPL red for 3+ consecutive days
        if not self.Portfolio[self.aapl].Invested and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)

        # ---- UPDATE PREVIOUS-VALUE TRACKERS ----
        self.prev_aapl_close = aapl_close
        self.prev_spy_close = spy_close
        if sma_ready:
            self.prev_sma100 = today_sma

